<template>
  <div class="container terminal-page">
    <div class="terminal-header"><div><div class="eyebrow">Execution / Live terminal</div><h1 class="page-title">Trade with context<span class="title-dot">.</span></h1><p class="page-subtitle">A focused view of market structure, bot intelligence, and execution readiness.</p></div><div class="terminal-actions"><span class="paper-pill"><i></i>{{ botStatus?.trading_mode || 'PAPER' }} MODE</span><button class="btn btn-secondary btn-sm" @click="refreshAll">↻ Refresh</button></div></div>

    <div class="terminal-toolbar card"><div class="pair-select-wrap"><span class="pair-token-avatar">{{ selectedPair?.symbol?.slice(0, 1) || '?' }}</span><label><small>MARKET</small><select v-model="selectedPairId" @change="loadPairData"><option value="" disabled>Select a watched pair</option><option v-for="pair in pairs" :key="pair.id" :value="pair.id">{{ pair.symbol }} · {{ pair.dex_name }}</option></select></label><span class="select-chevron">⌄</span></div><div class="market-quick-stats"><div><small>PRICE</small><strong>{{ formatPrice(selectedPair?.price_usd) }}</strong></div><div><small>24H CHANGE</small><strong :class="changeClass">{{ formatPercent(selectedPair?.price_change_24h) }}</strong></div><div><small>LIQUIDITY</small><strong>{{ formatMoney(selectedPair?.liquidity_usd) }}</strong></div><div><small>RISK</small><strong :class="riskClass">{{ selectedPair?.risk_level || 'PENDING' }}</strong></div></div></div>

    <div v-if="!selectedPairId" class="empty-terminal card"><span>⌁</span><h2>Select a market to begin</h2><p>Choose a watched pair above to load its chart, signals, and execution context.</p><router-link to="/scanner" class="btn btn-success">Open scanner →</router-link></div>
    <template v-else>
      <div class="terminal-grid"><section class="card chart-panel"><div class="section-heading"><div><div class="eyebrow">{{ selectedPair?.symbol || 'Market' }} / Price action</div><h2>{{ formatPrice(selectedPair?.price_usd) }} <span :class="changeClass">{{ formatPercent(selectedPair?.price_change_24h) }}</span></h2></div><div class="chart-controls"><span class="stream-state"><i :class="{ active: wsConnected }"></i>{{ wsConnected ? 'STREAMING' : 'POLLING' }}</span><button v-for="frame in timeframes" :key="frame.value" :class="{ active: timeframe === frame.value }" @click="timeframe = frame.value; loadCandles()">{{ frame.label }}</button></div></div><TerminalChart :candles="candles" :loading="loadingCandles" /><div class="chart-legend"><span><i class="green-dot"></i> Price</span><span><i class="purple-dot"></i> EMA trend</span><span>Volume · {{ formatMoney(latestSnapshot?.volume_24h_usd) }}</span></div></section>
        <aside class="card intelligence-panel"><div class="section-heading"><div><div class="eyebrow">AI intelligence</div><h2>Signal context</h2></div><span class="ai-orb">✦</span></div><div class="signal-score"><div class="score-ring"><strong>{{ signalScore }}<small>%</small></strong></div><div><small>AI CONFIDENCE</small><strong>{{ latestSignal?.signal_type || 'HOLD' }}</strong><span :class="latestSignal?.signal_type === 'BUY' ? 'positive' : 'muted'">{{ latestSignal ? 'Latest strategy signal' : 'Waiting for signal' }}</span></div></div><div class="intel-grid"><div><small>TREND</small><strong>{{ intelligence?.trend || 'UNKNOWN' }}</strong></div><div><small>RSI</small><strong>{{ numberOrDash(intelligence?.rsi) }}</strong></div><div><small>VOLUME RATIO</small><strong>{{ numberOrDash(intelligence?.volume_ratio) }}x</strong></div><div><small>ENTRY GATE</small><strong :class="intelligence?.entry_allowed ? 'positive' : 'negative'">{{ intelligence?.entry_allowed ? 'OPEN' : 'CLOSED' }}</strong></div></div><div class="signal-reason"><small>STRATEGY NOTE</small><p>{{ latestSignal?.reasons_pro?.[0] || intelligence?.reasons?.[0] || 'No active signal. The strategy engine is monitoring this market.' }}</p></div><button class="btn btn-secondary full-button" @click="goToToken">View full token analysis →</button></aside></div>

      <div class="terminal-lower-grid"><section class="card flow-panel"><div class="section-heading"><div><div class="eyebrow">Market flow</div><h2>Buy / sell pressure</h2></div><span class="muted-label">24H SNAPSHOT</span></div><div class="flow-bar"><span :style="{ width: `${buyPressure}%` }"></span></div><div class="flow-labels"><div><strong class="positive">{{ buyPressure.toFixed(1) }}%</strong><small>Buy pressure</small></div><div class="flow-center"><strong>{{ formatMoney(latestSnapshot?.volume_24h_usd) }}</strong><small>Total volume</small></div><div class="right-flow"><strong class="negative">{{ (100 - buyPressure).toFixed(1) }}%</strong><small>Sell pressure</small></div></div><div class="flow-stats"><div><span>Buys</span><strong>{{ latestSnapshot?.buy_count_24h ?? '—' }}</strong></div><div><span>Sells</span><strong>{{ latestSnapshot?.sell_count_24h ?? '—' }}</strong></div><div><span>Liquidity</span><strong>{{ formatMoney(selectedPair?.liquidity_usd) }}</strong></div></div></section>
        <section class="card positions-panel"><div class="section-heading"><div><div class="eyebrow">Risk exposure</div><h2>Open positions</h2></div><router-link to="/positions" class="view-all">Portfolio →</router-link></div><div v-if="positions.length" class="position-list"><div v-for="position in positions.slice(0, 3)" :key="position.id" class="position-row"><span class="position-symbol">{{ position.symbol?.slice(0, 1) || 'M' }}</span><div><strong>{{ position.symbol || selectedPair?.symbol }}</strong><small>Entry {{ formatPrice(position.entry_price) }}</small></div><div class="position-current"><strong>{{ formatPrice(position.current_price) }}</strong><small :class="position.pnl_percent >= 0 ? 'positive' : 'negative'">{{ formatPercent(position.pnl_percent) }}</small></div></div></div><div v-else class="panel-empty">No open positions for this market.</div></section>
        <section class="card execution-panel"><div class="section-heading"><div><div class="eyebrow">Execution</div><h2>Order panel</h2></div><span class="lock-label">▣ PAPER ONLY</span></div><div class="order-tabs"><button class="active">BUY</button><button>SELL</button></div><label class="amount-label">Amount in USD<input value="100" type="number" min="1" disabled /><span>$</span></label><div class="quick-amounts"><button>$25</button><button>$50</button><button>$100</button><button>MAX</button></div><div class="execution-notice">Manual execution requires quote and security approval. This terminal is currently read-only.</div><button class="btn btn-success full-button" disabled>Get quote to continue</button></section></div>

      <div class="card recent-panel"><div class="section-heading"><div><div class="eyebrow">Event stream</div><h2>Terminal activity</h2></div><span class="stream-state"><i :class="{ active: wsConnected }"></i>{{ wsConnected ? 'LIVE' : 'OFFLINE' }}</span></div><div class="event-list"><div v-for="event in activity" :key="event.id" class="event-row"><span class="event-dot" :class="event.tone"></span><div><strong>{{ event.title }}</strong><small>{{ event.detail }}</small></div><time>{{ event.time }}</time></div><div v-if="!activity.length" class="panel-empty">Waiting for terminal events...</div></div></div>
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { marketService, botService, portfolioService } from '../services/api'
import { useWebSocketStore } from '../stores/websocket'
import TerminalChart from '../components/terminal/TerminalChart.vue'

interface Pair { id: string; symbol: string; price_usd?: number; price_change_24h?: number; liquidity_usd?: number; risk_level?: string; dex_name?: string }
interface Candle { timestamp: string; open: number; high: number; low: number; close: number; volume?: number }
const router = useRouter(); const wsStore = useWebSocketStore(); const pairs = ref<Pair[]>([]); const selectedPairId = ref(''); const candles = ref<Candle[]>([]); const latestSnapshot = ref<any>(null); const latestSignal = ref<any>(null); const intelligence = ref<any>(null); const positions = ref<any[]>([]); const botStatus = ref<any>(null); const loadingCandles = ref(false); const timeframe = ref('minute'); const activity = ref<any[]>([]); const timeframes = [{ label: '1m', value: 'minute' }, { label: '5m', value: '5m' }, { label: '15m', value: '15m' }, { label: '1h', value: 'hour' }]; let poller: ReturnType<typeof setInterval> | undefined
const selectedPair = computed(() => pairs.value.find(pair => pair.id === selectedPairId.value)); const wsConnected = computed(() => wsStore.isConnected); const signalScore = computed(() => Math.round(Number(latestSignal.value?.confidence || (intelligence.value?.entry_allowed ? .78 : .42)) * 100)); const buyPressure = computed(() => { const buys = Number(latestSnapshot.value?.buy_count_24h || 0); const sells = Number(latestSnapshot.value?.sell_count_24h || 0); return buys + sells ? buys / (buys + sells) * 100 : 50 }); const changeClass = computed(() => Number(selectedPair.value?.price_change_24h || 0) >= 0 ? 'positive' : 'negative'); const riskClass = computed(() => ({ LOW: 'positive', MEDIUM: 'warning', HIGH: 'negative', CRITICAL: 'negative' }[selectedPair.value?.risk_level || ''] || 'muted'))
const formatMoney = (value?: number) => value == null ? '—' : `$${Number(value).toLocaleString('en-US', { maximumFractionDigits: 2 })}`; const formatPrice = (value?: number) => value == null ? '—' : Number(value) < .001 ? Number(value).toExponential(2) : `$${Number(value).toFixed(Number(value) < 1 ? 5 : 2)}`; const formatPercent = (value?: number) => value == null ? '—' : `${Number(value) > -1 && Number(value) < 1 ? (Number(value) * 100).toFixed(2) : Number(value).toFixed(2)}%`; const numberOrDash = (value?: number) => value == null ? '—' : Number(value).toFixed(1)
const loadPairs = async () => { const response = await marketService.getTerminalPairs(); pairs.value = response.data || []; if (!selectedPairId.value && pairs.value.length) { selectedPairId.value = pairs.value[0].id; await loadPairData() } }
const loadCandles = async () => { if (!selectedPairId.value) return; loadingCandles.value = true; try { const response = await marketService.getCandles(selectedPairId.value, timeframe.value, 100); candles.value = response.data?.items || [] } finally { loadingCandles.value = false } }
const loadPairData = async () => { if (!selectedPairId.value) return; try { const [snapshots, signals, chart, positionResponse] = await Promise.all([marketService.getPairSnapshots(selectedPairId.value, 1), marketService.getPairSignals(selectedPairId.value, 10), marketService.getChartIntelligence(selectedPairId.value, timeframe.value), portfolioService.listPositions('OPEN')]); latestSnapshot.value = snapshots.data?.[0] || null; latestSignal.value = signals.data?.[0] || null; intelligence.value = chart.data || null; positions.value = (positionResponse.data?.positions || []).filter((position: any) => position.pair_id === selectedPairId.value); await loadCandles() } catch (error) { console.error('Terminal load failed', error) } }
const refreshAll = async () => { await loadPairs(); await loadPairData() }; const goToToken = () => router.push(`/token/${selectedPairId.value}`); const addEvent = (topic: string, payload: any) => { const relevant = payload?.pair_id === selectedPairId.value || !payload?.pair_id; if (!relevant) return; const titles: Record<string, string> = { SIGNAL_GENERATED: 'New strategy signal', ORDER_STATUS_CHANGED: 'Order status changed', POSITION_UPDATED: 'Position updated' }; activity.value.unshift({ id: `${topic}-${Date.now()}`, title: titles[topic] || topic.replaceAll('_', ' '), detail: payload?.signal_type || payload?.status || 'Market event received', time: 'now', tone: topic.includes('ORDER') ? 'green' : topic.includes('SIGNAL') ? 'purple' : 'cyan' }); activity.value = activity.value.slice(0, 6); loadPairData() }
watch(() => wsStore.messages.length, () => { const event: any = wsStore.messages[wsStore.messages.length - 1]; if (event?.type === 'event') addEvent(event.topic, event.payload) }); onMounted(async () => { await loadPairs(); botService.getStatus().then(response => { botStatus.value = response.data }); wsStore.connect(import.meta.env.VITE_WS_URL || `${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/ws`); ['SIGNAL_GENERATED', 'ORDER_STATUS_CHANGED', 'POSITION_UPDATED', 'MARKET_PRICE_UPDATED'].forEach(topic => wsStore.subscribe(topic)); poller = setInterval(loadPairData, 30000) }); onUnmounted(() => { clearInterval(poller); wsStore.disconnect() })
</script>

<style scoped>
