pace}.signal-reason{padding:18px 0}.signal-reason p{margin:8px 0 0;color:var(--muted);font-size:.67rem;line-height:1.6}.full-button{width:100%;font-size:.64rem}.terminal-lower-grid{display:grid;grid-template-columns:1.1fr 1fr .8fr;gap:18px;margin-top:18px}.flow-bar{height:8px;overflow:hidden;border-radius:8px;background:rgba(255,101,119,.25)}.flow-bar span{display:block;height:100%;border-radius:8px;background:var(--accent)}.flow-labels{display:flex;align-items:end;justify-content:space-between;margin-top:12px}.flow-labels strong,.flow-labels small{display:block}.flow-labels strong{font:500 .95rem 'DM Mono',monospace}.flow-labels small{margin-top:3px;color:var(--muted);font-size:.58rem}.flow-center{text-align:center}.right-flow{text-align:right}.flow-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:22px;padding-top:14px;border-top:1px solid var(--line)}.flow-stats span,.flow-stats strong{display:block}.flow-stats span{color:var(--muted);font-size:.59rem}.flow-stats strong{margin-top:4px;font:500 .7rem 'DM Mono',monospace}.position-list{display:grid}.position-row{display:flex;align-items:center;gap:9px;padding:10px 0;border-top:1px solid var(--line)}.position-symbol{display:grid;width:27px;height:27px;place-items:center;border-radius:8px;background:var(--surface-soft);color:var(--accent);font-size:.65rem;font-weight:800}.position-row strong,.position-row small{display:block}.position-row strong{font-size:.66rem}.position-row small{color:var(--muted);font-size:.56rem}.position-current{margin-left:auto;text-align:right}.position-current strong{font:500 .64rem 'DM Mono',monospace}.panel-empty{padding:30px 0;color:var(--muted);font-size:.66rem;text-align:center}.order-tabs{display:flex;gap:5px;margin-bottom:15px}.order-tabs button{flex:1;padding:7px;border:0;border-radius:6px;background:transparent;color:var(--faint);font:500 .6rem 'DM Mono',monospace}.order-tabs button.active{background:rgba(0,245,139,.11);color:var(--accent)}.amount-label{position:relative;display:block;color:var(--muted);font-size:.62rem}.amount-label input{display:block;width:100%;height:38px;margin-top:7px;padding:0 28px 0 11px;border:1px solid var(--line);border-radius:7px;background:var(--surface-raised);color:var(--text);outline:0;font:500 .72rem 'DM Mono',monospace}.amount-label span{position:absolute;right:12px;bottom:10px;color:var(--faint);font:500 .65rem 'DM Mono',monospace}.quick-amounts{display:flex;gap:4px;margin:8px 0 14px}.quick-amounts button{flex:1;padding:5px 2px;border:1px solid var(--line);border-radius:5px;background:transparent;color:var(--muted);font:500 .55rem 'DM Mono',monospace}.execution-notice{padding:9px;margin-bottom:11px;border-radius:6px;background:rgba(255,200,87,.07);color:var(--warning);font-size:.57rem;line-height:1.45}.recent-panel{margin-top:18px}.event-list{display:grid}.event-row{display:flex;align-items:center;gap:11px;padding:12px 0;border-top:1px solid var(--line)}.event-dot{width:7px;height:7px;border-radius:50%;background:var(--cyan)}.event-dot.green{background:var(--accent)}.event-dot.purple{background:var(--purple)}.event-row strong,.event-row small{display:block}.event-row strong{font-size:.67rem}.event-row small{margin-top:2px;color:var(--muted);font-size:.59rem}.event-row time{margin-left:auto;color:var(--faint);font:500 .57rem 'DM Mono',monospace}
@media(max-width:1050px){.terminal-lower-grid{grid-template-columns:1fr 1fr}.execution-panel{grid-column:1/-1}.market-quick-stats{gap:15px}}
@media(max-width:760px){.terminal-header{display:block}.terminal-actions{justify-content:space-between;margin-top:18px}.terminal-toolbar{display:block}.market-quick-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:15px;margin-top:18px;padding-top:15px;border-top:1px solid var(--line)}.terminal-grid,.terminal-lower-grid{grid-template-columns:1fr}.chart-panel,.intelligence-panel{min-height:0}.chart-controls{flex-wrap:wrap;justify-content:flex-end}.chart-controls .stream-state{display:none}.terminal-chart-wrap{height:300px}.terminal-lower-grid{display:grid}.execution-panel{grid-column:auto}.terminal-page .page-title{font-size:2.2rem}}
</style>
